mapper.select:
select * from `orders`

     and user_id = #{userId}
     and user_name like concat('%', #{userName}, '%')
     and order_no like concat('%', #{orderNo}, '%')
     and status = #{status}
     and order_status = #{orderStatus}
     and time >= #{startTime}
     and time <= #{endTime}

order by id desc

mapper.update:
update `orders` set order_no = #{orderNo}, user_id = #{userId}, user_name = #{userName},
    total_price = #{totalPrice}, status = #{status}, delivery_type = #{deliveryType}, order_status = #{orderStatus}, address = #{address}, deliver = #{deliver}, time = #{time}
where id = #{id}
